  if (typeof amount !== "number" || amount <= 0) {
    throw new TypeError("\u0627\u0644\u0645\u0628\u0644\u063A \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0633\u062D\u0628\u0647 \u0644\u0627\u0632\u0645 \u0623\u0646 \u064A\u0643\u0648\u0646 \u0631\u0642\u0645\u064B\u0627 \u0645\u0648\u062C\u0628\u064B\u0627");
  }

  if (amount > balance) {
    throw new RangeError("\u0627\u0644\u0631\u0635\u064A\u062F \u0627\u0644\u062D\u0627\u0644\u064A \u063A\u064A\u0631 \u0643\u0627\u0641\u064D \u0644\u0625\u062A\u0645\u0627\u0645 \u0627\u0644\u0639\u0645\u0644\u064A\u0629");
  }

  return balance - amount;
